implementation.solution:
function minStack(ops) {
  const stack = [], mins = [], out = [];
  for (const op of ops) {
    if (op === 'pop') {
      stack.pop();
      mins.pop();
    } else if (op === 'min') {
      out.push(mins.length > 0 ? mins[mins.length - 1] : null);
    } else {
      const n = Number(op.slice(5));
      stack.push(n);
      mins.push(mins.length > 0 ? Math.min(n, mins[mins.length - 1]) : n);
    }
  }
  return out;
}

