implementation.solution:
function hashMapOps(ops, buckets) {
  const table = Array.from({ length: buckets }, () => []);
  const hash = (k) => {
    let h = 0;
    for (let i = 0; i < k.length; i++) h = (h * 31 + k.charCodeAt(i)) % buckets;
    return h;
  };
  const out = [];
  for (const op of ops) {
    const parts = op.split(' ');
    const cmd = parts[0], key = parts[1];
    const chain = table[hash(key)];
    const at = chain.findIndex((e) => e[0] === key);
    if (cmd === 'set') {
      if (at >= 0) chain[at][1] = Number(parts[2]);
      else chain.push([key, Number(parts[2])]);
    } else if (cmd === 'get') {
      out.push(at >= 0 ? chain[at][1] : null);
    } else if (cmd === 'del') {
      if (at >= 0) chain.splice(at, 1);
    }
  }
  return out;
}

