      let smallest = i;
      if (l < h.length && h[l] < h[smallest]) smallest = l;
      if (r < h.length && h[r] < h[smallest]) smallest = r;
      if (smallest === i) break;
      const t = h[i]; h[i] = h[smallest]; h[smallest] = t;
      i = smallest;
    }
