function connectedComponents(n, edges) {
  const adj = [];
  for (let i = 0; i < n; i++) adj.push([]);
  for (const e of edges) { adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); }
  const seen = new Array(n).fill(false);
  const out = [];
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    const comp = [];
    const queue = [s];
    seen[s] = true;
    let head = 0;
    while (head < queue.length) {
      const v = queue[head++];
      comp.push(v);
      for (const w of adj[v]) if (!seen[w]) { seen[w] = true; queue.push(w); }
    }
    comp.sort(function (a, b) { return a - b; });
    out.push(comp);
  }
  return out;
}

