function hasCycleDirected(n, edges) {
  const adj = [];
  for (let i = 0; i < n; i++) adj.push([]);
  for (const e of edges) adj[e[0]].push(e[1]);
  const colour = new Array(n).fill(0);
  let found = false;
  function go(v) {
    colour[v] = 1;
    for (const w of adj[v]) {
      if (colour[w] === 1) { found = true; return; }
      if (colour[w] === 0) { go(w); if (found) return; }
    }
    colour[v] = 2;
  }
  for (let s = 0; s < n && !found; s++) if (colour[s] === 0) go(s);
  return found;
}

