function makeNode() {
  return { children: Object.create(null), terminal: false };
}

function insert(root, word) {
  let node = root;
  for (const ch of word) {
    if (!node.children[ch]) node.children[ch] = makeNode();
    node = node.children[ch];
  }
  node.terminal = true;
}

function has(root, word) {
  let node = root;
