function touch(h, id) {
  let node = h.nodes[id];
  if (node) detach(h, node);
  else { node = { id, prev: null, next: null }; h.nodes[id] = node; h.size++; }
  node.next = h.head;
  if (h.head) h.head.prev = node;
  h.head = node;
  if (!h.tail) h.tail = node;
  if (h.size > h.capacity) {
    const drop = h.tail;
    detach(h, drop);
    delete h.nodes[drop.id];
    h.size--;
  }
  return h;
}

