function runVault(capacity, commands) {
  var index = Object.create(null);
  var records = [];
  var heap = [];
  var pending = 0;

  function before(x, y) {
    var a = records[x], b = records[y];
    if (a.priority !== b.priority) return a.priority < b.priority;
    return x < y;
  }
  function heapPush(seq) {
    heap.push(seq);
    var i = heap.length - 1;
    while (i > 0) {
      var p = (i - 1) >> 1;
      if (!before(heap[i], heap[p])) break;
      var t = heap[i]; heap[i] = heap[p]; heap[p] = t;
      i = p;
    }
  }
  function heapPop() {
    var top = heap[0];
    var last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      var i = 0;
      for (;;) {
        var l = 2 * i + 1, r = l + 1, m = i;
        if (l < heap.length && before(heap[l], heap[m])) m = l;
        if (r < heap.length && before(heap[r], heap[m])) m = r;
        if (m === i) break;
        var t = heap[i]; heap[i] = heap[m]; heap[m] = t;
        i = m;
      }
    }
    return top;
  }

  var head = null, tail = null, nodes = Object.create(null), listSize = 0;
  function detach(node) {
    if (node.prev) node.prev.next = node.next; else head = node.next;
    if (node.next) node.next.prev = node.prev; else tail = node.prev;
    node.prev = null; node.next = null;
  }
  function touch(id) {
    var node = nodes[id];
    if (node) detach(node);
    else { node = { id: id, prev: null, next: null }; nodes[id] = node; listSize++; }
    node.next = head;
    if (head) head.prev = node;
    head = node;
    if (!tail) tail = node;
    if (listSize > capacity) {
      var drop = tail;
      detach(drop);
      delete nodes[drop.id];
      listSize--;
    }
  }

  var out = [];
  for (var k = 0; k < commands.length; k++) {
    var cmd = commands[k], op = cmd[0];
    if (op === "submit") {
      var sid = cmd[1];
      if (index[sid] !== undefined) { out.push(false); continue; }
      var seq = records.length;
      records.push({ id: sid, priority: cmd[2], cancelled: false });
      index[sid] = seq;
      heapPush(seq);
      pending++;
      out.push(true);
    } else if (op === "cancel") {
      var cid = cmd[1];
      if (index[cid] === undefined) { out.push(false); continue; }
      records[index[cid]].cancelled = true;
      delete index[cid];
      pending--;
      out.push(true);
    } else if (op === "run") {
      var ran = null;
      while (heap.length) {
        var s = heapPop();
        if (records[s].cancelled) continue;
        ran = records[s].id;
        delete index[ran];
        pending--;
        touch(ran);
        break;
      }
      out.push(ran);
    } else if (op === "history") {
      var ids = [];
      for (var n = head; n; n = n.next) ids.push(n.id);
      out.push(ids);
    } else if (op === "stats") {
      out.push({ pending: pending, heapSize: heap.length, historySize: listSize });
    }
  }
  return out;
}
